CREATE TABLE incidents(id BINARY(16) PRIMARY KEY,incident_number VARCHAR(255) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,severity VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,assignee_id BINARY(16),related_deployment_id BINARY(16),created_at TIMESTAMP(6) NOT NULL,acknowledged_at TIMESTAMP(6),resolved_at TIMESTAMP(6),postmortem TEXT,revision BIGINT NOT NULL);
CREATE TABLE incident_affected_services(id BINARY(16) PRIMARY KEY,incident_id BINARY(16) NOT NULL,service_name VARCHAR(255) NOT NULL,UNIQUE(incident_id,service_name),FOREIGN KEY(incident_id) REFERENCES incidents(id) ON DELETE CASCADE);
CREATE TABLE incident_timeline(id BINARY(16) PRIMARY KEY,incident_id BINARY(16) NOT NULL,actor_id BINARY(16) NOT NULL,type VARCHAR(100) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,INDEX idx_incident_timeline(incident_id,created_at),FOREIGN KEY(incident_id) REFERENCES incidents(id) ON DELETE CASCADE);